export const PartnerDashboardPage: React.FC = () => {
    const { user, partners, setCurrentPage, t } = useAppContext();
    const { openChatForOrderId, openOrderDetailsForOrderId } = useNavigation();
    const [section, setSection] = useState<PartnerSection>('dashboard');

    useEffect(() => {
        if (openChatForOrderId) {
            setSection('orders');
        }
    }, [openChatForOrderId]);

    useEffect(() => {
        if (openOrderDetailsForOrderId) {
            setSection('dashboard');
        }
    }, [openOrderDetailsForOrderId]);

    const partner = useMemo(() => {
        if (!user?.partnerId) return null;
        return partners.find(p => p.id === user.partnerId);
    }, [user, partners]);

    if (!user?.partnerId) {
        return (
            <div className="text-center p-8 bg-white dark:bg-slate-800 rounded-2xl shadow-card dark:border dark:border-slate-700">
                <h2 className="text-2xl font-bold mb-4 text-red-600">{t('partnerDashboardPage.accessDenied')}</h2>
                <p className="text-gray-600 dark:text-slate-300 mb-6">{t('partnerDashboardPage.partnersOnly')}</p>
                <button
                // FIX: Pass a PageObject to setCurrentPage instead of a string.
                onClick={() => setCurrentPage({ name: 'home' })}
                className="px-6 py-2 bg-brand-blue text-white font-semibold rounded-lg hover:bg-opacity-90"
                >
                {t('partnerDashboardPage.backToHome')}
                </button>
            </div>
        )
    }

    const renderAccessDenied = () => {
        return (
            <div className="text-center p-8 bg-white dark:bg-slate-800 rounded-2xl shadow-card dark:border dark:border-slate-700">
                <h2 className="text-2xl font-bold mb-4 text-red-600">{t('partnerDashboardPage.accessDenied')}</h2>
                <p className="text-gray-600 dark:text-slate-300 mb-6">
                    {t('partnerDashboardPage.insufficientPermissions')}
                </p>
                <button
                    onClick={() => setSection('dashboard')}
                    className="px-6 py-2 bg-brand-blue text-white font-semibold rounded-lg hover:bg-opacity-90"
                >
                    {t('partnerDashboardPage.backToDashboard')}
                </button>
            </div>
        );
    };

    const renderSection = () => {
        const hasAccess = (allowedRoles: UserRole[]) => {
            return user?.role && allowedRoles.includes(user.role as UserRole);
        };

        switch (section) {
            case 'orders':
                return <OrderManagement />;
            case 'profile':
                if (!hasAccess(['partner-owner', 'partner-manager'])) return renderAccessDenied();
                return <ProfileManagement />;
            case 'promotions':
                if (!partner?.enabledFeatures?.promotions || !hasAccess(['partner-owner', 'partner-manager'])) return renderAccessDenied();
                return <PartnerPromoManagement />;
            case 'invoicing':
                if (!partner?.enabledFeatures?.invoiceGenerator || !hasAccess(['partner-owner', 'partner-manager'])) return renderAccessDenied();
                return <InvoicingPage />;
            case 'financials':
                if (!partner?.enabledFeatures?.financials || !hasAccess(['partner-owner'])) return renderAccessDenied();
                return <PartnerFinancials />;
            case 'analytics':
                if (!partner?.enabledFeatures?.analytics || !hasAccess(['partner-owner', 'partner-manager'])) return renderAccessDenied();
                return <PartnerAnalytics />;
            case 'team':
                if (!partner?.enabledFeatures?.teamManagement || !hasAccess(['partner-owner'])) return renderAccessDenied();
                return <TeamManagement />;
            case 'security':
                if (!hasAccess(['partner-owner'])) return renderAccessDenied();
                return <SecurityPage />;
            case 'api-integrations':
                if (!partner?.enabledFeatures?.apiAccess || !hasAccess(['partner-owner'])) return renderAccessDenied();
                return <ApiIntegrationsPage />;
            case 'automation':
                if (!partner?.enabledFeatures?.advancedAutomation || !hasAccess(['partner-owner'])) return renderAccessDenied();
                return <AutomationPage />;
            case 'subscription':
                if (!hasAccess(['partner-owner'])) return renderAccessDenied();
                return <SubscriptionPage />;
            case 'inventory':
                if (!hasAccess(['partner-owner', 'partner-manager'])) return renderAccessDenied();
                return <InventoryManagement />;
            case 'delivery':
                if (!hasAccess(['partner-owner'])) return renderAccessDenied();
                return <DeliverySettings />;
            case 'dashboard':
            default:
                return <Dashboard setSection={setSection} />;
        }
    }

    const handleNavClick = (target: PartnerSection, isExternal?: boolean) => {
        if (isExternal) {
            // FIX: Pass a PageObject to setCurrentPage instead of a string.
            setCurrentPage({ name: 'support' });
        } else {
            setSection(target);
        }
    };

    const sidebar = <PartnerSidebar partner={partner} activeSection={section} onSectionClick={handleNavClick} />;

    const mobileTitle = useMemo(() => {
        const key = `partnerDashboardPage.${section}`;
        const defaultText = section.charAt(0).toUpperCase() + section.slice(1);
        return t(key, { default: defaultText });
    }, [section, t]);

    return (
       <DashboardLayout sidebar={sidebar} mobileTitle={mobileTitle}>
            <div key={section} className="animate-fade-in">
                {renderSection()}
            </div>
       </DashboardLayout>
    )
}

import React, { createContext, useState, useContext, useCallback, useEffect, useMemo } from 'react';
// FIX: Add missing ID type import
import { Partner, LogisticsPartner, SiteContent, Review, User, PartnerApplication, SupportTicket, Chat, Service, PromoCode, ApplicationStatus, TicketStatus, TicketMessage, ChatMessage, LoyaltySettings, ReferralSettings, Order, AppNotification, Advertisement, ApplicationSettings, PartnerType, Article, OptimizedRoute, AdminSection, AdminPermissions, NotificationAnalytic, BulkNotificationTarget, WebhookEvent, ActivityLog, ActivityLogAction, DataContextType, TeamMemberRole, AutomationSettings, TrackingSettings, SubscriptionPlan, Invoice, CommissionSettings, RefundRequest, ID, Currency, InventoryItem, DeliverySettings, SecurityAlert, NotificationType } from '../types';
import * as api from '../constants';
import { useLanguageContext } from './LanguageContext.tsx';
import { useAuth } from './AuthContext.tsx';
import { useNotification } from './NotificationContext.tsx';
import { appEvents } from '../utils/events.ts';
import { ResponseSanitizer } from '../backend/utils/sanitize';
import { useLocalStorage } from '../hooks/useLocalStorage.tsx';

const emptySiteContent: SiteContent = {
  hero: { title: '', subtitle: '' },
  howItWorksSteps: [],
  faq: [],
};


const DataContext = createContext<DataContextType | undefined>(undefined);

export const useData = () => {
  const context = useContext(DataContext);
  if (!context) {
    throw new Error('useData must be used within a DataProvider');
  }
  return context;
};

export const DataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { t } = useLanguageContext();
  const { user, updateUser } = useAuth();
  const { addNotification } = useNotification();

  const [isLoading, setIsLoading] = useState(true);
  const [partners, setPartners] = useState<Partner[]>([]);
  const [services, setServices] = useState<Service[]>([]);
  const [logisticsPartners, setLogisticsPartners] = useState<LogisticsPartner[]>([]);
  const [reviews, setReviews] = useState<Review[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [orderHistory, setOrderHistory] = useState<Order[]>([]);
  const [partnerApplications, setPartnerApplications] = useState<PartnerApplication[]>([]);
  const [supportTickets, setSupportTickets] = useState<SupportTicket[]>([]);
  const [chats, setChats] = useState<Chat[]>([]);
  const [promoCodes, setPromoCodes] = useState<PromoCode[]>([]);
  const [rawSiteContent, setRawSiteContent] = useState<SiteContent>(emptySiteContent);
  const [loyaltySettings, setLoyaltySettings] = useState<LoyaltySettings>({ isEnabled: true, pointsPerDollar: 10, pointsToDollar: 100 });
  const [referralSettings, setReferralSettings] = useState<ReferralSettings>({ isEnabled: true, referrerBonusPoints: 500, refereeDiscountAmount: 5 });
  const [notificationAnalytics, setNotificationAnalytics] = useState<NotificationAnalytic[]>([]);
  const [advertisements, setAdvertisements] = useState<Advertisement[]>([]);
  const [applicationSettings, setApplicationSettings] = useState<ApplicationSettings>({
      [PartnerType.PRESSING]: true,
      [PartnerType.LAVANDIER]: true,
      [PartnerType.LOGISTICS]: true,
  });
  const [trackingSettings, setTrackingSettings] = useState<TrackingSettings>({ gtmContainerId: '', metaPixelId: '' });
  const [commissionSettings, setCommissionSettings] = useState<CommissionSettings>({ globalRate: 0, byServiceType: {} });
  const [subscriptionPlans, setSubscriptionPlans] = useState<SubscriptionPlan[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [refundRequests, setRefundRequests] = useState<RefundRequest[]>([]);
  const [selectedCurrency, setSelectedCurrency] = useLocalStorage<Currency>('selectedCurrency', 'USD');

  const formatPrice = useCallback((priceUSD: number, targetCurrency?: Currency) => {
    const currency = targetCurrency || selectedCurrency;
    if (currency === 'CDF') {
        const priceCDF = priceUSD * api.EXCHANGE_RATES.CDF;
        return `${priceCDF.toLocaleString('fr-FR')} FC`;
    }
    return `$${priceUSD.toFixed(2)}`;
  }, [selectedCurrency]);

  const fetchData = useCallback(async () => {
    try {
        const data = await api.fetchAllData();
        setPartners(data.partners);
        setServices(data.services);
        setLogisticsPartners(data.logisticsPartners);
        setReviews(data.reviews);
        setUsers(data.users);
        setOrderHistory(data.orderHistory);
        setPartnerApplications(data.partnerApplications.filter(app => app.status === ApplicationStatus.PENDING));
        setSupportTickets(data.supportTickets);
        setChats(data.chats);
        setPromoCodes(data.promoCodes);
        setLoyaltySettings(data.loyaltySettings);
        setReferralSettings(data.referralSettings);
        setAdvertisements(data.advertisements);
        setNotificationAnalytics(data.notificationAnalytics);
        setApplicationSettings(data.applicationSettings);
        setTrackingSettings(data.trackingSettings);
        setCommissionSettings(data.commissionSettings);
        setRawSiteContent(data.siteContent);
        setSubscriptionPlans(data.subscriptionPlans);
        setInvoices(data.invoices);
        setRefundRequests(data.refundRequests);
    } catch (error) {
        console.error("Failed to fetch data:", error);
    }
  }, []);

  useEffect(() => {
    const initialFetch = async () => {
        await fetchData();
        setIsLoading(false);
    };

    initialFetch(); // Initial fetch

    // Listen for data changes from anywhere in the app
    const unsubscribe = appEvents.on('data_changed', fetchData);
    return () => unsubscribe();
  }, [fetchData]);

