            >
                {!notification.isRead && <div className="w-2.5 h-2.5 bg-brand-blue rounded-full mt-1.5 shrink-0 animate-pulse"></div>}
                <div className={`flex-grow ${notification.isRead ? 'pl-[26px]' : ''}`}>
