                )}
                {canChat && (
                    <button
                        onClick={() => onOpenChat(order)}
                        className="p-2 text-slate-500 hover:bg-slate-200 rounded-full"
                        title={t('partnerOrderManagement.openChat')}
                    >
                       <Icon name="chatBubble" className="w-5 h-5"/>
                    </button>
                )}
            </td>
        </tr>
    );
};

