    await simulateDelay();
    const newOrder: Order = {
        id: `ORD-${Date.now()}`, userId, ...orderData,
        status: OrderStatus.AWAITING_CONFIRMATION,
        trackingHistory: [{ status: OrderStatus.AWAITING_CONFIRMATION, time: new Date().toISOString() }],
